// src/lib/blockchain/kross/deployed.config.ts
// AUTO-GENERATED by KrossBuild dApp pipeline — chain-specific deployment config.
// Do not hardcode addresses elsewhere; read from here.
export const DEPLOYED_CONFIG = {
  "chain": "kross",
  "chainId": "N",
  "nodeUrl": "https://nodes.krossexplorer.com",
  "explorerUrl": "https://krossexplorer.com",
  "addressPrefix": "3K",
  "nativeCoin": {
    "name": "Kross",
    "symbol": "KSS",
    "decimals": 8
  },
  "language": "RIDE",
  "contracts": []
} as const;
export default DEPLOYED_CONFIG;

/**
 * Resolve the deployed marketplace dApp address.
 * Priority:
 *   1. A contract entry named "marketplace" in DEPLOYED_CONFIG.contracts
 *   2. The VITE_KROSS_MARKETPLACE_DAPP env var
 *   3. Empty string (UI guards against an unconfigured address)
 */
function resolveMarketplaceDApp(): string {
  const contracts = DEPLOYED_CONFIG.contracts as ReadonlyArray<{
    name?: string;
    address?: string;
  }>;
  const fromContracts = contracts.find(
    (c) => c?.name?.toLowerCase() === 'marketplace'
  )?.address;
  const fromEnv =
    typeof import.meta !== 'undefined'
      ? (import.meta as any).env?.VITE_KROSS_MARKETPLACE_DAPP
      : undefined;
  return fromContracts ?? fromEnv ?? '';
}

/**
 * Deployed Kross marketplace dApp configuration.
 * Consumed by marketplace-queries.ts and the Marketplace page.
 */
export const MARKETPLACE_CONFIG = {
  dAppAddress: resolveMarketplaceDApp(),
  functions: {
    list: 'listNFT',
    buy: 'buyNFT',
    cancel: 'cancelListing',
  },
} as const;
